#include <string>
#include <type_traits>

struct Tracked {
  static inline int alive = 0;
  int value;
  explicit Tracked(int v) : value(v) { ++alive; }
  ~Tracked() { --alive; }
};

TEST("owns and destroys the object exactly once") {
  Tracked::alive = 0;
  {
    UniquePtr<Tracked> p(new Tracked(1));
    CHECK_EQ(Tracked::alive, 1);
    CHECK_EQ(p->value, 1);
    CHECK_EQ((*p).value, 1);
  }
  CHECK_EQ(Tracked::alive, 0);
}

TEST("default is null and false") {
  UniquePtr<Tracked> p;
  CHECK(p.get() == nullptr);
  CHECK(!p);
}

TEST("copying is not allowed") {
  CHECK(!std::is_copy_constructible_v<UniquePtr<Tracked>>);
  CHECK(!std::is_copy_assignable_v<UniquePtr<Tracked>>);
  CHECK(!(std::is_convertible_v<UniquePtr<Tracked>, bool>));  // operator bool is explicit
}

TEST("moving transfers ownership") {
  Tracked::alive = 0;
  {
    UniquePtr<Tracked> a(new Tracked(2));
    Tracked* raw = a.get();
    UniquePtr<Tracked> b(std::move(a));
    CHECK(a.get() == nullptr);
    CHECK(b.get() == raw);
    CHECK_EQ(Tracked::alive, 1);
  }
  CHECK_EQ(Tracked::alive, 0);
}

TEST("move assignment deletes the old object") {
  Tracked::alive = 0;
  {
    UniquePtr<Tracked> a(new Tracked(1));
    UniquePtr<Tracked> b(new Tracked(2));
    b = std::move(a);
    CHECK_EQ(Tracked::alive, 1);
    CHECK_EQ(b->value, 1);
    CHECK(a.get() == nullptr);
  }
  CHECK_EQ(Tracked::alive, 0);
}

TEST("self-move-assignment keeps the object") {
  Tracked::alive = 0;
  {
    UniquePtr<Tracked> a(new Tracked(3));
    UniquePtr<Tracked>& alias = a;
    a = std::move(alias);
    CHECK(a.get() != nullptr);
    CHECK_EQ(a->value, 3);
  }
  CHECK_EQ(Tracked::alive, 0);
}

TEST("release gives up ownership") {
  Tracked::alive = 0;
  Tracked* raw;
  {
    UniquePtr<Tracked> p(new Tracked(4));
    raw = p.release();
    CHECK(p.get() == nullptr);
  }
  CHECK_EQ(Tracked::alive, 1);  // still alive: we own it now
  delete raw;
}

TEST("reset replaces and deletes") {
  Tracked::alive = 0;
  UniquePtr<Tracked> p(new Tracked(1));
  p.reset(new Tracked(2));
  CHECK_EQ(Tracked::alive, 1);
  CHECK_EQ(p->value, 2);
  p.reset();
  CHECK_EQ(Tracked::alive, 0);
  CHECK(!p);
}

TEST("make_unique_ptr forwards constructor arguments") {
  auto s = make_unique_ptr<std::string>(3, 'x');
  CHECK_EQ(*s, std::string("xxx"));
}

