#include <utility>

template <typename T>
class UniquePtr {
 public:
  UniquePtr() noexcept = default;
  explicit UniquePtr(T* p) noexcept : p_(p) {}
  ~UniquePtr() { delete p_; }

  UniquePtr(const UniquePtr&) = delete;             // one owner only
  UniquePtr& operator=(const UniquePtr&) = delete;

  UniquePtr(UniquePtr&& other) noexcept : p_(other.release()) {}
  UniquePtr& operator=(UniquePtr&& other) noexcept {
    // release() nulls `other` first, so even `a = std::move(a)` is safe:
    // we take back our own pointer, and reset deletes only the (null) old value.
    reset(other.release());
    return *this;
  }

  T* get() const noexcept { return p_; }
  T* release() noexcept { return std::exchange(p_, nullptr); }
  void reset(T* p = nullptr) noexcept {
    T* old = std::exchange(p_, p);  // update first, then delete, so a throwing destructor can't leave us dangling
    delete old;
  }

  T& operator*() const { return *p_; }
  T* operator->() const noexcept { return p_; }
  explicit operator bool() const noexcept { return p_ != nullptr; }

 private:
  T* p_ = nullptr;
};

template <typename T, typename... Args>
UniquePtr<T> make_unique_ptr(Args&&... args) {
  return UniquePtr<T>(new T(std::forward<Args>(args)...));
}
